      navigator.clipboard.writeText(text).then(() => {
        if (copyUtcBtn) {
          copyUtcBtn.textContent = 'Copied!';
        }
        const announcement = document.getElementById('copy-announcement');
        if (announcement) announcement.textContent = 'Copied!';
        setTimeout(() => {
