    if (!copyBtn) return;
    const announcement = document.getElementById('copy-stats-announcement');
    const originalLabel = copyBtn.textContent;

    const fallback = (text) => {
      const ta = document.createElement('textarea');
      ta.value = text;
      ta.style.position = 'fixed';
